var e=[{id:1,text:"¿Qué es una familia extensa?",sorted:!1,options:[{text:"Aquella combinada con más de dos progenitores.",correct:!1},{text:"La formada por un solo progenitor.",correct:!1},{text:"Aquella que está compuesta por parejas homosexuales.",correct:!1},{text:"Aquella que está compuesta por varias generaciones bajo el mismo techo.",correct:!0}]},{id:2,text:"¿Que son las TRIC?",sorted:!1,options:[{text:"Tecnologías de la Relación, la Información y la Comunicación.",correct:!0},{text:"Teoría de la Relatividad, la Integración y la Comunidad.",correct:!1},{text:"Trastornos entre las Relaciones Infantiles y la Comunidad.",correct:!1},{text:"Tecnologías de los Recursos, la Innovación y la Comunicación.",correct:!1}]},{id:3,text:"Siemens es el máximo representante:",sorted:!1,options:[{text:"De la Pedagogía Crítica.",correct:!1},{text:"Del Conectivismo.",correct:!0},{text:"Del Cognitivismo.",correct:!1},{text:"De la Escuela Nueva.",correct:!1}]},{id:4,text:"¿Cómo se denomina al modelo de participación de las familias en la educación propuesto por Epstein?",sorted:!1,options:[{text:"Teoría de la interconexión.",correct:!1},{text:"Teoría casual.",correct:!1},{text:"Teoría de las Tres esferas superpuestas e interconectadas.",correct:!0},{text:"Syneducation.",correct:!1}]},{id:5,text:"¿Cuántas leyes de la Alfabetización Mediática e informacional (AMI) determina la UNESCO?",sorted:!1,options:[{text:"3",correct:!1},{text:"8",correct:!1},{text:"12",correct:!1},{text:"5",correct:!0}]},{id:6,text:"¿Con que otro nombre se conoce a la familia tradicional?",sorted:!1,options:[{text:"Familia clásica",correct:!1},{text:"Familia típica",correct:!1},{text:"Familia general",correct:!1},{text:"Familia nuclear",correct:!0}]},{id:7,text:"¿Qué caracteriza a la sociedad líquida?",sorted:!1,options:[{text:"La revolución digital",correct:!1},{text:"Los acelerados cambios que sufre la sociedad",correct:!0},{text:"La retroalimentación en diferido",correct:!1},{text:"La retroalimentación inmediata",correct:!1}]},{id:8,text:"Señala el condicionante en la transformación digital de la educación",sorted:!1,options:[{text:"Carencia de competencia digital y AMI",correct:!0},{text:"Exceso de evidencias de innovación",correct:!1},{text:"Falta de presupuesto para la digitalización",correct:!1},{text:"El alumnado",correct:!1}]},{id:9,text:"¿Qué regula las funciones pedagógicas de los docentes?",sorted:!1,options:[{text:"El Consejo escolar",correct:!1},{text:"El estatuto de los trabajadores",correct:!1},{text:"Las Juntas de evaluación",correct:!1},{text:"Las Leyes educativas",correct:!0}]},{id:10,text:"Señala cuál es una de las funciones de la familia.",sorted:!1,options:[{text:"Profesionalización",correct:!1},{text:"Crianza",correct:!0},{text:"Digitalización",correct:!1},{text:"Vigilancia",correct:!1}]},{id:11,text:"Educar es:",sorted:!1,options:[{text:"Un proceso perfectivo de la persona que se produce de manera intencional y permanentemente inacabado.",correct:!0},{text:"Un proceso perfectivo de la persona que se produce de manera espontánea en una forma acabada.",correct:!1},{text:"Un proceso imperfectivo y empobrecedor",correct:!1},{text:"Un sistema de valores definido.",correct:!1}]},{id:13,text:"Cuando hablamos a de AMI, ¿a qué hacemos referencia?",sorted:!1,options:[{text:"Acción para las mejoras de la infancia.",correct:!1},{text:"Alfabetización Mediática Informacional.",correct:!0},{text:"Adiestramiento de los medios informáticos.",correct:!1},{text:"Asesoramiento de los medios de información.",correct:!1}]},{id:14,text:"¿En qué año se estableció en España el derecho a la educación?",sorted:!1,options:[{text:"1985, con la LODE.",correct:!1},{text:"1949, coincidiendo con la Declaración de los Derechos Humanos.",correct:!1},{text:"2013, con la LOMCE.",correct:!1},{text:"1978, con la Constitución Española.",correct:!0}]},{id:15,text:"¿Con qué se corresponden el concepto de mLearning?",sorted:!1,options:[{text:"Aprendizaje digital",correct:!1},{text:"Aprendizaje mediado",correct:!1},{text:"Aprendizaje automático",correct:!1},{text:"Aprendizaje móvil ubicuo",correct:!0}]},{id:16,text:"¿Qué caracteriza a la familia en la actualidad?",sorted:!1,options:[{text:"Convivir bajo el mismo techo.",correct:!0},{text:"Convivir en casas separadas.",correct:!1},{text:"Convivir de manera aislada.",correct:!1},{text:"No convivir necesariamente bajo el mismo techo.",correct:!1}]},{id:17,text:"La LOGSE establece la escolaridad obligatoria",sorted:!1,options:[{text:"Desde los 6 a los 18 años",correct:!1},{text:"Desde los 6 a los 14 años",correct:!1},{text:"Desde los 6 a los 16 años",correct:!0},{text:"Desde los 3 a los 16 años",correct:!1}]},{id:18,text:"¿Cuáles son los actores principales de la Educación?",sorted:!1,options:[{text:"Los medios de comunicación.",correct:!1},{text:"Los gobiernos y las leyes.",correct:!1},{text:"El profesor y el alumno.",correct:!1},{text:"Educando, educador, familia y sociedad.",correct:!0}]},{id:19,text:"El marco competencial digital docente que se integra en nuestro sistema educativo es el:",sorted:!1,options:[{text:"PLE",correct:!1},{text:"EVA",correct:!1},{text:"DigComOrg",correct:!1},{text:"DigComEdu",correct:!0}]},{id:20,text:"En la constitución española (1978) el derecho a la educación está desarrollado en el artículo:",sorted:!1,options:[{text:"5",correct:!1},{text:"27",correct:!0},{text:"30",correct:!1},{text:"20",correct:!1}]},{id:21,text:"Dentro de los saberes esenciales para el futuro de Morín se encuentra:",sorted:!1,options:[{text:"Afrontar incertidumbres.",correct:!1},{text:"Estudio profundo y holístico del conocimiento humano.",correct:!1},{text:"Comprensión mutua entre los seres humanos.",correct:!1},{text:"Todas las opciones son correctas.",correct:!0}]},{id:22,text:"En la escuela tradicional, el logocentrismo hace referencia a:",sorted:!1,options:[{text:"Todo el proceso de enseñanza y aprendizaje se agota en el manual escolar.",correct:!1},{text:"Ninguna es correcta.",correct:!1},{text:"El maestro tiene todo el poder, impone los contenidos y el ritmo de trabajo sin tener en cuenta al alumno.",correct:!1},{text:"El programa ocupa un lugar central. No se tiene en cuenta el interés o el momento evolutivo del niño.",correct:!0}]},{id:23,text:"La necesidad de la educación en el ser humano está relacionada con:",sorted:!1,options:[{text:"Su necesidad de autorealización.",correct:!1},{text:"Su precariedad física.",correct:!1},{text:"Su necesidad de interaccionar con los otros.",correct:!1},{text:"Todas son correctas.",correct:!0}]},{id:24,text:"El concepto que se contrapone al paidocentrismo es:",sorted:!1,options:[{text:"El enciclopedismo.",correct:!1},{text:"El logocentrismo.",correct:!1},{text:"El magistricentrismo",correct:!0},{text:"Ninguna es correcta.",correct:!1}]},{id:25,text:"Rosseau plantea los siguientes puntos vinculados con el movemento de la escuela nueva:",sorted:!1,options:[{text:"Descubrimiento de la infancia, naturalismo y espontaneismo.",correct:!0},{text:"Logocentrismo y paidocentrismo.",correct:!1},{text:"Cognitivismo y constructivismo.",correct:!1},{text:"Ninguna es correcta.",correct:!1}]},{id:26,text:"Según Illich:",sorted:!1,options:[{text:"Hay que apostar por una educación institucionalizada.",correct:!1},{text:"La escuela ampara a los ya privilegiados.",correct:!0},{text:"El saber auténtico proviene de las experiencias que se producen en la escuela.",correct:!1},{text:"Ninguna es correcta.",correct:!1}]},{id:27,text:"En la escuela tradicional, el enciclopedismo hace referencia a:",sorted:!1,options:[{text:"Todo el proceso de enseñanza y aprendizaje se agota en el manual escolar.",correct:!0},{text:"El programa ocupa un lugar central. No se tiene en cuenta el interés o el momento evolutivo del niño.",correct:!1},{text:"El maestro tiene todo el poder, impone los contenidos y el ritmo de trabajo sin tener en cuenta al alumno.",correct:!1},{text:"Ninguna es correcta.",correct:!1}]},{id:28,text:"Algunas de las características de la nueva escuela son:",sorted:!1,options:[{text:"Metodologías activas.",correct:!1},{text:"Educación artística.",correct:!1},{text:"Paidocentrismo.",correct:!1},{text:"Todas son correctas.",correct:!0}]},{id:29,text:"El movimiento de la nueva escuela:",sorted:!1,options:[{text:"Se refiere a un método en particular.",correct:!1},{text:"Es un movimiento uniforme.",correct:!1},{text:"Se refiere a una escuela en particular.",correct:!1},{text:"Ninguna es correcta.",correct:!0}]},{id:30,text:"Makarenko propone:",sorted:!1,options:[{text:"La educación como formación del hombre para la sociedad comunista.",correct:!0},{text:"La escuela summerhill que se resume en dos grandes conceptos: libertad y felicidad.",correct:!1},{text:"La confianza en la naturaleza del niño.",correct:!1},{text:"El antiautoritarismo: no castigos, no exámenes, no premios.",correct:!1}]},{id:31,text:"Dentro de los autores de la nueva escuela, Lorenzi Milani:",sorted:!1,options:[{text:"Acuña los conceptos de educación bancaria y educación liberadora.",correct:!1},{text:"Propone la escuela de summerhill.",correct:!1},{text:"Se engloba dentro de las teorías personalistas.",correct:!0},{text:"Se engloba dentro de las teorías desescolarizadoras.",correct:!1}]},{id:32,text:"En el código deontológico de la profesión docente se incluyen los compromisos y deberes en relación a:",sorted:!1,options:[{text:"El alumnado, las familias y tutores del alumnado, la institución educativa, los compañeros, la profesión y la sociedad.",correct:!0},{text:"El alumnado, las familias y tutores del alumnado, la institución educativa, los compañeros, las entidades supranacionales y la sociedad.",correct:!1},{text:"El alumnado, las familias y tutores del alumnado, la institución educativa, los compañeros, la política y la sociedad.",correct:!1},{text:"Ninguna es correcta.",correct:!1}]},{id:33,text:"Illich propone:",sorted:!1,options:[{text:"Los conceptos de educación bancaria y educación liberadora.",correct:!1},{text:"La escuela de summerhill.",correct:!1},{text:"Las teorías desescolarizadoras.",correct:!0},{text:"Ninguna es correcta.",correct:!1}]},{id:34,text:"Ferrer y Guardía impulsó:",sorted:!1,options:[{text:"La relación con el medio.",correct:!1},{text:"La coeducación de sexos y clases.",correct:!1},{text:"La enseñanza racionalista y científica.",correct:!1},{text:"Todas las opciones son correctas.",correct:!0}]},{id:35,text:"En la escuela tradicional, el magistrocentrismo hace referencia a:",sorted:!1,options:[{text:"El maestro tiene todo el poder, impone los contenidos y el ritmo de trabajo sin tener en cuenta al alumno.",correct:!0},{text:"Todo el proceso de enseñanza y aprendizaje se agota en el manual escolar.",correct:!1},{text:"El programa ocupa un lugar central. No se tiene en cuenta el interés o el momento evolutivo del niño.",correct:!1},{text:"Ninguna correcta.",correct:!1}]},{id:36,text:"Señala cual NO se corresponde con las competencias establecidas por la LOMCE:",sorted:!1,options:[{text:"Competencias sociales y cívicas.",correct:!1},{text:"Competencia transformadora.",correct:!0},{text:"Competencia digital.",correct:!1},{text:"Sentido de iniciativa y espíritu emprendedor.",correct:!1}]},{id:37,text:"Tolstoi se encuentra estrechamente vinculado a la ideología",sorted:!1,options:[{text:"Comunista.",correct:!1},{text:"Sociocrítica.",correct:!1},{text:"Libertaria.",correct:!0},{text:"Ninguna correcta.",correct:!1}]},{id:38,text:"Freire propone:",sorted:!1,options:[{text:"La escuela de Summerhill.",correct:!1},{text:"Los conceptos de educación bancaria y educación liberadora.",correct:!0},{text:"Teorías desecolarizadoras.",correct:!1},{text:"Ninguna correcta.",correct:!1}]},{id:39,text:"Neill propone:",sorted:!1,options:[{text:"La escuela de summerhill que se resume en dos grandes conceptos: libertad y felicidad.",correct:!0},{text:"El concepto de educación bancaria y liberadora.",correct:!1},{text:"Las bases de la pedagogía popular.",correct:!1},{text:"La educación como formación del hombre para la sociedad comunista.",correct:!1}]},{id:40,text:"Delors propone los siguientes pilares del aprendizaje:",sorted:!1,options:[{text:"Aprender a conocer, aprender a hacer, aprender a vivir juntos y aprender a comprometerse.",correct:!1},{text:"Aprender a conocer, aprender a hacer, aprender a vivir juntos y aprender a compartir.",correct:!1},{text:"Aprender a conocer, aprender a hacer, aprender a vivir juntos y aprender a ser.",correct:!0},{text:"Aprender a conocer, aprender a hacer, aprender a vivir juntos y aprender a dialogar.",correct:!1}]},{id:41,text:"El ser humano es un ser inacabado. ¿Desde qué perspectiva se incluye en la unidad didáctica?",sorted:!1,options:[{text:"Porque necesita del otro y de los otros para desarrollar todas sus posibilidades.",correct:!0},{text:"Porque necesita del otro y de los otros para desarrollar alguna de sus posibilidades.",correct:!1},{text:"Es una falacia.",correct:!1}]},{id:42,text:"La Escuela Nueva es,",sorted:!1,options:[{text:"un movimiento de renovación pedagógico surgido a comienzos del siglo XXI.",correct:!1},{text:"un movimiento de renovación pedagógico surgido a finales del Siglo XIX y principios del XX.",correct:!0},{text:"Es una línea que intenta mantener la escuela tradicional.",correct:!1}]},{id:43,text:"Rousseau, aportó varias cuestiones importantes a la educación. Entre ellas, cabría destacar,",sorted:!1,options:[{text:"el descubrimiento de la pubertad.",correct:!1},{text:"la falta de curiosidad en los niños.",correct:!1},{text:"el descubrimiento de la infancia.",correct:!0}]},{id:44,text:"En relación a las características de la escuela tradicional, cabría destacar,",sorted:!1,options:[{text:"la situación del niño en el triángulo educativo, siempre favorable.",correct:!1},{text:"el paidocentrismo.",correct:!1},{text:"el magistocentrismo.",correct:!0}]},{id:45,text:"la primera escuela nueva, fue creada por C. Reddie en el año 1889:",sorted:!0,options:[{text:"Verdadero",correct:!0},{text:"Falso",correct:!1}]},{id:46,text:"Makarenko dirigió la Colonia Máximo Gorki durante el comienzo de la revolución Rusa, en 1917",sorted:!0,options:[{text:"Verdadero",correct:!1},{text:"Falso",correct:!0}]},{id:47,text:"Francisco Ferrer i Guardia propuso una enseñanza,",sorted:!1,options:[{text:"religiosa y racional.",correct:!1},{text:"laica y racional.",correct:!0},{text:"religiosa y basada en el criterio místico.",correct:!1}]},{id:48,text:"Alexander S. Neil, fundador de la Escuela Summerhill, estableció como principales pilares metodológicos:",sorted:!1,options:[{text:"el magistocentrismo y el paidocentrismo.",correct:!1},{text:'el "dejar hacer" y el magistocentrismo.',correct:!1},{text:'el "dejar hacer" y la asamblea.',correct:!0}]},{id:49,text:"La multiculturalidad hace referencia:",sorted:!1,options:[{text:"Al hecho de que haya, en un mismo espacio o territorio, más de una cultura.",correct:!1},{text:"Al hecho de que haya una relación, principalmente, de coexistencia, pero no de convivencia, entre distintas culturas.",correct:!0},{text:"Al hecho de que se identifiquen culturas diferentes dentro de un común, pero sin que implique la pérdida de ninguna de ellas.",correct:!1},{text:"Ninguna de las respuestas es correcta.",correct:!1}]},{id:50,text:"La segunda socialización hace referencia a:",sorted:!1,options:[{text:"Cuando un individuo adquiere el conocimiento como la personalidad necesaria para convertirse en un miembro pleno de la sociedad.",correct:!1},{text:"Cuando un individuo se introduce en nuevos ámbitos de su sociedad (por ejemplo, al adquirir una profesión).",correct:!0},{text:"Cuando un individuo se distancia de una sociedad.",correct:!1},{text:"Ninguna de las respuestas es correcta.",correct:!1}]},{id:51,text:"La interculturalidad hace referencia:",sorted:!1,options:[{text:"Al hecho de que se identifiquen culturas diferentes dentro de una común, pero sin que implique la pérdida de ninguna de ellas.",correct:!0},{text:"Ninguna de las respuestas es correcta.",correct:!1},{text:"Al hecho de que haya, en un mismo espacio o territorio, más de una cultura.",correct:!1},{text:"Al hecho de que haya una relación, principalmente, de coexistencia, pero no de convivencia, entre distintas culturas.",correct:!1}]},{id:52,text:"Dentro de las dinámicas tóxicas de los centros educativos se encuentra:",sorted:!1,options:[{text:"Retener nuevos docentes.",correct:!1},{text:"Recurrir a colegas como recurso.",correct:!1},{text:"Empleados que se afanan en fomentar rumores y difamaciones.",correct:!0},{text:"Utilizar lenguaje pragmático.",correct:!1}]},{id:53,text:"El primer autor en abordar la educación como rama de la sociología (Según Bonal, 1998) fue:",sorted:!1,options:[{text:"Durkheim, E.",correct:!0},{text:"Marx, K.",correct:!1},{text:"Weber, M.",correct:!1},{text:"Ninguna de las respuestas es correcta.",correct:!1}]},{id:54,text:"La educación es un fenómeno social debido, entre otras cuestiones, a que:",sorted:!1,options:[{text:"Es permeable y susceptible a los cambios sociales.",correct:!1},{text:"Legitima y está interrelacionado con un diseño laboral y productivo.",correct:!1},{text:"Es un fenómeno cultural humano.",correct:!1},{text:"Todas las respuestas son correctas.",correct:!0}]},{id:55,text:"Entre los objetivos para 2015 que establece el Marco de Acción de Dakar: Educación para Todos (2000) se encuentra:",sorted:!1,options:[{text:"Que todos los niños puedan acceder a una educación desde los tres años de edad.",correct:!0},{text:"Que todos los niños puedan acceder a una educación desde los seis años de edad.",correct:!1},{text:"Que todos los niños puedan acceder a una educación desde los cero años.",correct:!1},{text:"Ninguna de las respuestas es correcta.",correct:!1}]},{id:56,text:"Dentro de las pautas positivas para los docentes y directivos NO se encuentra:",sorted:!1,options:[{text:"Utilizar un lenguaje pragmático.",correct:!1},{text:"Pasar tiempo diagnosticando problemas y no enfrentarse a ellos.",correct:!0},{text:"Promover las responsabilidades de todos.",correct:!1},{text:"Buscar el apoyo de otros docentes.",correct:!1}]},{id:57,text:"Las características de los derechos fundamentales son:",sorted:!1,options:[{text:"Imprescriptibles, inalienables, irrenunciables y universales.",correct:!0},{text:"Imprescriptibles, inalienables, personales y universales.",correct:!1},{text:"Imprescriptibles, inalienables, flexibles y universales.",correct:!1},{text:"Ninguna de las respuestas es correcta.",correct:!1}]},{id:58,text:"El sistema social implica:",sorted:!1,options:[{text:"Que sus partes se conecten con un objetivo.",correct:!1},{text:"Que el sistema esté en equilibrio.",correct:!1},{text:"Que sus partes estén, de alguna forma, conectadas.",correct:!1},{text:"Todas las respuestas son correctas.",correct:!0}]},{id:59,text:"Cuál de los siguientes enunciados NO se encuentran dentro de las 5 tesis de Toro (2010) para establecer valores positivos:",sorted:!1,options:[{text:"En democracias, lo público se construye desde la política.",correct:!0},{text:"Ser ciudadano es tener un proyecto ético y de participación.",correct:!1},{text:"Es, a través de la organización, como yo puedo ser actor social.",correct:!1},{text:"La organización genera la autorregulación.",correct:!1}]},{id:60,text:"Dentro de las teorías y corrientes sociológicas en educación, en la teoría crítica y de resistencia:",sorted:!1,options:[{text:"La educación se concibe como un sistema controlado por la dominación ideológica de un grupo de élite.",correct:!1},{text:"Se destaca como el contexto escolar replica el mundo laboral.",correct:!1},{text:"La escuela se considera un ámbito de transformación donde el docente hace uso de una pedagogía crítica con conciencia social.",correct:!0},{text:"Se enfatiza la idea de transmisión cultural entre clases sociales, une el éxito escolar con el capital cultural heredado de la familia.",correct:!1}]},{id:61,text:"Dentro de las teorías y corrientes sociológicas en educación, el funcionalismo:",sorted:!1,options:[{text:"Enfatiza la idea de transmisión cultural entre clases sociales, une el éxito escolar con el capital cultural heredado de la familia.",correct:!1},{text:"Se centra en el sistema educativo bajo un prisma de transmisión de contenidos y técnicas.",correct:!0},{text:"La educación se concibe como un sistema controlado por la dominación ideológica de un grupo de élite.",correct:!1},{text:"La escuela se considera un ámbito de transformación donde el docente hace uso de una pedagogía crítica con conciencia social.",correct:!1}]},{id:62,text:"Que un derecho sea imprescriptible quiere decir que:",sorted:!1,options:[{text:"No se puede renunciar a él.",correct:!1},{text:"No se adquiere ni pierde por el siempre transcurso del tiempo.",correct:!0},{text:"No se puede transferir a otro titular.",correct:!1},{text:"Ninguna de las respuestas es correcta.",correct:!1}]},{id:63,text:"La pluriculturalidad hace referencia:",sorted:!1,options:[{text:"Al hecho de que haya, en un mismo espacio o territorio, más de una cultura.",correct:!0},{text:"Al hecho de que haya una relación de coexistencia, pero no de convivencia, entre distintas culturas.",correct:!1},{text:"Al hecho de que se identifiquen culturas diferentes dentro de una común, pero sin que implique la pérdida de ninguna de ellas.",correct:!1}]},{id:64,text:"Dentro de las teorías y corrientes sociológicas de educación, en la teoría comprensiva o interpretativa:",sorted:!1,options:[{text:"La educación se concibe como un sistema controlado por la dominación ideológica de un grupo de élite.",correct:!0},{text:"Se centra en el sistema educativo bajo un prisma transmisión de contenidos y técnicas.",correct:!1},{text:"La escuela se considera un ámbito de transformación donde el docente hace uso de una pedagogía crítica con conciencia social.",correct:!1},{text:"Enfatiza la idea de transmisión cultural entre clases sociales, une el éxito escolar con el capital cultural heredado de la familia.",correct:!1}]},{id:65,text:"Dentro de las teorías y corrientes sociológicas en educación, en la teoría de la correspondencia:",sorted:!1,options:[{text:"La escuela se considera un ámbito de transformación donde el docente hace uso de la pedagogía crítica con conciencia social.",correct:!1},{text:"La educación se concibe como un sistema controlado por la dominación ideológica de un grupo de élite.",correct:!1},{text:"Se destaca como el contexto escolar replica el mundo laboral.",correct:!0},{text:"Se enfatiza la idea de transmisión cultural entre clases sociales, une el éxito escolar con el capital cultural heredado de la familia.",correct:!1}]},{id:66,text:"Dentro de las teorías y corrientes sociológicas en educación, en la teoría de la reproducción:",sorted:!1,options:[{text:"Se enfatiza la idea de transmisión cultural entre clases sociales, une el éxito escolar con el capital cultural heredado de la familia.",correct:!0},{text:"Se destaca como el contexto escolar replica el mundo laboral.",correct:!1},{text:"La educación se concibe como un sistema controlado por la dominación ideológica de un grupo de élite.",correct:!1},{text:"La escuela se considera un ámbito de transformación donde el docente hace uso de una pedagogía crítica con conciencia social.",correct:!1}]},{id:67,text:"La constitución española (1978) indica que la enseñanza básica:",sorted:!1,options:[{text:"Es voluntaria y no gratuita.",correct:!1},{text:"Es gratuita y voluntaria.",correct:!1},{text:"Es obligatoria y gratuita.",correct:!0},{text:"Es obligatorio, pero no gratuita.",correct:!1}]},{id:68,text:"La socialización puede definirse como",sorted:!1,options:[{text:"el proceso por el cual una persona en edad adulta adquiere tanto el conocimiento, pues la personalidad ya la ha creado, necesaria para convertirse en un miembro de la comunidad.",correct:!1},{text:"el proceso por el cual una persona, principalmente un niño, adquiere tanto el conocimiento como la personalidad necesaria para convertirse en un miembro de la sociedad.",correct:!0},{text:"el proceso por el cual una persona pasa de niño a adulto.",correct:!1}]},{id:69,text:"Por estructura social entendemos",sorted:!1,options:[{text:"patrones perdurables que se establecen en las relaciones entre distintas partes de una sociedad.",correct:!0},{text:"la referencia a patrones perdurables que se establecen en las relaciones entre distintas sociedades.",correct:!1},{text:"una referencia a patrones limitados en el tiempo breve, que se establecen entre las distintas partes de una sociedad.",correct:!1}]},{id:70,text:"Entre los factores por los que cabría indicar que la educación es un fenómeno social, cabría destacar,",sorted:!1,options:[{text:"su carácter de fenómeno cultural humano.",correct:!0},{text:"su carácter independiente de la cultura humana.",correct:!1},{text:"la desconexión entre educación e ideologías.",correct:!1}]},{id:71,text:"Para Weber, la sociología pretendía,",sorted:!1,options:[{text:"dar explicación a la acción humana en su contexto histórico.",correct:!0},{text:"dar explicación al surgimiento de la humanidad como entidad.",correct:!1},{text:"dar explicación a la acción humano, de forma independiente a su contexto histórico.",correct:!1}]},{id:72,text:"Fuentealba Weber planteó dos objetivos necesarios en relación al estudio de la educación desde cualquier perspectiva sociológica. Son:",sorted:!1,options:[{text:"el análisis de las relaciones entre educación y sociedad, con independencia de la reciprocidad; y, el examen del sistema educacional.",correct:!1},{text:"el análisis de las relaciones entre educación y sociedad, junto a sus influencias recíprocas; y, el examen del sistema educacional, siempre en un marco general que no incluya subsistemas y elementos.",correct:!1},{text:"el análisis de las relaciones entre educación y sociedad, junto a sus influencias recíprocas; y el examen del sistema educacional, de los subsistemas y elementos que lo componen.",correct:!0}]},{id:73,text:"La sociología de la educación es una disciplina,",sorted:!1,options:[{text:"explicativa y descriptiva, como las didácticas.",correct:!1},{text:"Principalmente de intervención en el contexto, como la pedagogía.",correct:!1},{text:"explicativa y descriptiva, en contraste con la pedagogía y las didácticas.",correct:!0}]},{id:74,text:"En la teoría de la correspondencia,",sorted:!1,options:[{text:"se destaca cómo el contexto escolar replica el mundo laboral.",correct:!0},{text:"se destaca la implicación del profesorado por encima de cualquier otra participación.",correct:!1},{text:"se destaca la importancia del currículo como forma de estructurar de forma correcta la sociedad.",correct:!1}]},{id:75,text:"Educación y valores, un binomio complejo. Según Porta,",sorted:!1,options:[{text:"la educación debe estar al margen de los valores, pues es un ámbito que corresponde a la familia.",correct:!1},{text:"la educación no puede estar al margen de la cuestión de los valores.",correct:!0},{text:"Es importante diferenciar ambas cuestiones de forma clara, de igual manera que se diferencian el bios y el logos del ser humano.",correct:!1}]},{id:76,text:"La pluriculturalidad puede definirse como:",sorted:!1,options:[{text:"La presencia de varias culturas en un territorio, perfectamente integradas y con unos niveles altos de interrelación.",correct:!1},{text:"la existencia en un mismo territorio de varias culturas, las cuales presentan índices de interrelación normalmente superficiales.",correct:!0},{text:"el establecimiento en un mismo territorio de más de una cultura, que se encuentran totalmente desunidas y enfrentadas.",correct:!1}]},{id:77,text:"Una de las características del estilo educativo indulgente es:",sorted:!1,options:[{text:"La afirmación del poder.",correct:!1},{text:"La tolerancia a todos los impulsos del niño.",correct:!0},{text:"La comunicación unidireccional.",correct:!1},{text:"El clima autoritario.",correct:!1}]},{id:78,text:"Dentro de los agentes que influyen en la educación, podemos citar:",sorted:!1,options:[{text:"La cultura, la política y la economía.",correct:!0},{text:"Sólo la política, por cuanto el currículo es producto de los partidos gobernantes.",correct:!1},{text:"La economía, por cuanto en la actualidad las grandes corporaciones superan en poder a los gobiernos.",correct:!1},{text:"Solo la cultura.",correct:!1}]},{id:79,text:"Una de las implicaciones que supone una acción educativa es:",sorted:!1,options:[{text:"La objetividad.",correct:!1},{text:"El afianzamiento antes que el cambio.",correct:!1},{text:"La ausencia de neutralidad.",correct:!0},{text:"La indiferencia ante un contexto, pues educamos de forma generalista.",correct:!1}]},{id:80,text:"Según Torio:",sorted:!1,options:[{text:"La implicación paterna suele ser mayor en la relación familia- escuela.",correct:!1},{text:"Cuando se lleva a cabo la participación no aparece como una cuestión limitada a ciertas actividades.",correct:!1},{text:"Todos los padres muestran una disposición absoluta a participar.",correct:!1},{text:"La implicación materna suele ser mayor en la relación familia-escuela.",correct:!0}]},{id:81,text:"Una de las características del estilo educativo negligente es:",sorted:!1,options:[{text:"La madurez alcanzada.",correct:!1},{text:"La atención a las necesidades de los niños.",correct:!1},{text:"La reflexión como parte del proceso educativo.",correct:!1},{text:"La escasa motivación y capacidad de esfuerzo.",correct:!0}]},{id:82,text:"Al nacer nos integramos en un sistema que conjugan entre sus componentes:",sorted:!1,options:[{text:'Los hábitos de crianza y cuidado infantil, entendidos como acciones "socialmente aceptadas".',correct:!0},{text:"La inocuidad del medio físico.",correct:!1},{text:"La presión que ejerce el mundo laboral.",correct:!1},{text:"La ausencia de creencias que han de aplicarse, pues en un estado laico está prohibido.",correct:!1}]},{id:83,text:"La colaboración familia-escuela",sorted:!1,options:[{text:"No es necesaria, pues hay que establecer límites claros entre la educación y la instrucción.",correct:!1},{text:"Es necesaria, pese a las percepciones contrarias que en ocasiones se detectan tanto entre las familias como entre el profesorado.",correct:!0},{text:"Necesita reglamentaciones por parte de las autoridades, puesto que en España sigue siendo un proceso carente de ellas.",correct:!1},{text:"Ninguna es correcta.",correct:!1}]},{id:84,text:"Respecto a la influencia de la estructura familiar en la educación, parece resultar como factor principal",sorted:!1,options:[{text:"La presencia siempre de padre y madre.",correct:!1},{text:"La calidad de las relaciones interpersonales que se producen entre sus miembros.",correct:!0},{text:"La moral inquebrantable.",correct:!1},{text:"Ninguna es correcta.",correct:!1}]},{id:85,text:"En general, las formas de concebir al niño y actuar respecto a él son guiadas por:",sorted:!1,options:[{text:"El contexto social y cultural de los grupos dominantes",correct:!1},{text:"El contexto global.",correct:!1},{text:"El contexto social y cultural en el que nazca el niño.",correct:!0},{text:"Ninguna es correcta.",correct:!1}]},{id:86,text:"Uno de los principales motivos por los cuales los docentes, en muchas ocasiones, no consideran precisa la participación de los padres es:",sorted:!1,options:[{text:"La inexperiencia en materia educativa.",correct:!0},{text:"Las quejas continuadas.",correct:!1},{text:"El conformismo detectado, que evita el diálogo.",correct:!1},{text:"La falta de temas que tratar.",correct:!1}]},{id:87,text:"A mayor participación familiar en el proceso de aprendizaje...",sorted:!1,options:[{text:"Menor tendrá que ser el esfuerzo realizado por los educados.",correct:!1},{text:"Mayores esfuerzos realizarán los padres, sin mayores valoraciones.",correct:!1},{text:"Mayores serán sus probabilidades de alcanzar un rendimiento óptimo.",correct:!0},{text:"Menores serán sus probabilidades de alcanzar un rendimiento óptimo.",correct:!1}]},{id:88,text:"Una de las principales implicaciones que se detectan con frecuencia en los hijos en un proceso de divorcio es:",sorted:!1,options:[{text:"La inadaptación del niño a sus nuevos cuidadores, aspecto que es sistemático.",correct:!1},{text:"La inadaptación psicológica, que se origina antes de que se produzca el divorcio como consecuencia de la relación hostil que se vive en casa.",correct:!0},{text:"La falta de cuidados que se detecta.",correct:!1},{text:"Ninguna de las anteriores es correcta.",correct:!1}]},{id:89,text:"Una de las características del estilo educativo autoritario es:",sorted:!1,options:[{text:"La comunicación unidireccional.",correct:!0},{text:"La falta de normas.",correct:!1},{text:"La promoción del intercambio y la comunicación abierta.",correct:!1},{text:"El clima afectivo y democrático del hogar.",correct:!1}]},{id:90,text:"Una de las características del estilo educativo democrático es:",sorted:!1,options:[{text:"La promoción del intercambio y la comunicación abierta.",correct:!0},{text:"La falta de explicaciones.",correct:!1},{text:"La disciplina conductual.",correct:!1},{text:"El clima autoritario.",correct:!1}]},{id:91,text:"La participación de las familias en el contexto educativo:",sorted:!1,options:[{text:"No requiere conocimiento de causa.",correct:!1},{text:"Solo se requiere en momentos puntuales.",correct:!1},{text:"Ha de ser un proceso permanente.",correct:!0},{text:"Ninguna de las respuestas es correcta.",correct:!1}]},{id:92,text:"Para conseguir el objetivo de la educación actual, es necesario:",sorted:!1,options:[{text:"Adquirir cultura, crear cultura y transmitir cultura.",correct:!0},{text:"Únicamente adquirir cultura, pues la creación y la transmisión son acciones previas y posteriores al acto educativo.",correct:!1},{text:"Prestar atención.",correct:!1},{text:"Ninguna de las respuestas es correcta.",correct:!1}]},{id:93,text:"Participar significa:",sorted:!1,options:[{text:"Tomar parte, no únicamente exigir, controlar y protestar.",correct:!0},{text:"Defender los derechos, de la misma forma que las otras partes nos exigen cumplir nuestras obligaciones.",correct:!1},{text:"Imponernos cuando nuestras ideas sean las correctas.",correct:!1},{text:"Tener derecho a la crítica, aunque no nos responsabilicemos en el conocimiento de nuestras tareas.",correct:!1}]},{id:94,text:"Respecto al nivel socioeconómico de las familias podría desprenderse:",sorted:!1,options:[{text:"Su absoluta irrelevancia en el proceso educativo, de acuerdo con los principales estudios.",correct:!1},{text:"Cierta correlación entre el nivel socioeconómico alto y el rendimiento académico, si bien es un debate abierto.",correct:!0},{text:"Ninguna de las anteriores es correcta.",correct:!1},{text:"Lo único que permite es la obtención por parte de los educados de grandes regalos.",correct:!1}]},{id:95,text:"La estructura familiar hace referencia a:",sorted:!1,options:[{text:"El número de integrantes de la familia.",correct:!0},{text:"El conjunto de las tres últimas generaciones, pues todas ellas participan en un proceso educativo.",correct:!1},{text:"El conjunto de las tres últimas generaciones en cuanto a los familiares vivos, porque solo ellos participan en el proceso educativo.",correct:!1},{text:"Ninguna de las respuestas es correcta.",correct:!1}]},{id:96,text:'Podemos definir "clima familiar" como:',sorted:!1,options:[{text:"El afecto mostrado al niño, sin necesidad de reciprocidad.",correct:!1},{text:"El conjunto de conductas de apoyo, afectividad y razonamiento que fomenta la autonomía personal.",correct:!0},{text:"Un conjunto de conductas que no han de caracterizarse por su solidaridad.",correct:!1},{text:"Ninguna de las respuestas es correcta",correct:!1}]},{id:97,text:"En la Ley General de Educación:",sorted:!1,options:[{text:"La educación se generaliza desde los 6 a los 16 años.",correct:!1},{text:"La educación se generaliza desde los 6 a los 14 años.",correct:!0},{text:"La educación se generaliza desde los 3 a los 14 años.",correct:!1},{text:"La educación se generaliza desde los 0 a los 14 años.",correct:!1}]},{id:98,text:"Dentro de los principios del aprendizaje dialógico, Flecha y Puigvert dan importancia a la igualdad de diferencias, entendida como:",sorted:!1,options:[{text:"Contraria al principio de diversidad que regula la igualdad y que ha regido algunas reformas educativas.",correct:!0},{text:"Un principio de la integración.",correct:!1},{text:"Ninguna de las opciones es correcta.",correct:!1},{text:"Inherente al principio de diversidad.",correct:!1}]},{id:99,text:"En la LOGSE, se estable que en el Consejo Escolar del Centro:",sorted:!1,options:[{text:"No hubiera representación de los padres y madres de los alumnos.",correct:!1},{text:"Tres de los representantes de los padres fuera designado por le Asociación de Padres más representativa del centro.",correct:!1},{text:"Uno de los representantes de los padres Fuera designado por le Asociación de Padres más representativa del centro.",correct:!0},{text:"Ninguna de las opciones es correcta.",correct:!1}]},{id:100,text:"Las claves para las comunidades de aprendizaje son (Elboj, Puigdellívol, Soler, Valls):",sorted:!1,options:[{text:"Participación, individualización del aprendizaje, expectativas positivas y progreso permanente.",correct:!1},{text:"Participación, centralidad del aprendizaje, expectativas positivas e innovación tecnológica permanente.",correct:!1},{text:"Participación, centralidad del aprendizaje, expectativas positivas y progreso permanente.",correct:!0},{text:"Ninguna de las opciones es correcta.",correct:!1}]},{id:101,text:"La ley de Instrucción Pública establece los siguientes niveles educativos:",sorted:!1,options:[{text:"Primera enseñanza, segunda enseñanza y enseñanza superior.",correct:!0},{text:"Primera enseñanza, segunda enseñanza y tercera enseñanza.",correct:!1},{text:"Primera enseñanza y segunda enseñanza.",correct:!1},{text:"Enseñanza básica y enseñanza obligatoria.",correct:!1}]},{id:102,text:"La participación de los padres en los sistemas educativos europeos:",sorted:!1,options:[{text:"Es algo consolidado y, además, contemplado en las respectivas legislaciones de cada país.",correct:!1},{text:"No está consolidado, entre otros motivos, porque no se contempla en las legislaciones de los países.",correct:!1},{text:"Está consolidado, aunque no se contempla en las legislaciones de los países.",correct:!1},{text:"Ninguna de las opciones es correcta.",correct:!0}]},{id:103,text:"Dentro de los principios del aprendizaje dialógico, Flecha y Puigvert dan importancia al diálogo igualitario, entendido como:",sorted:!1,options:[{text:"Una manera de considerar las diferentes aportaciones desde la validez de los argumentos, no desde criterios vinculados a una relación jerárquica.",correct:!0},{text:"Una manera de considerar las diferentes aportaciones desde criterios basados en la relación jerárquica.",correct:!1},{text:"Una manera de considerar las diferentes aportaciones desde criterios basados en la imposición autoritaria.",correct:!1},{text:"Ninguna de las opciones es correcta.",correct:!1}]},{id:104,text:"¿Qué ley educativa se considera la gran introductora de la familia en el contexto educativo?",sorted:!1,options:[{text:"LOMCE.",correct:!1},{text:"LOGSE.",correct:!1},{text:"LOE.",correct:!1},{text:"LGE.",correct:!0}]},{id:105,text:"Las fases del proceso de transformación hacia una comunidad de aprendizaje son:",sorted:!1,options:[{text:"Sensibilización, toma de decisión, evaluación, selección de prioridades, planificación.",correct:!1},{text:"Sensibilización, toma de decisión, sueño, selección de prioridades, planificación.",correct:!0},{text:"Sensibilización, toma de decisión, evaluación, selección de prioridades, justificación.",correct:!1},{text:"Ninguna de las opciones es correcta.",correct:!1}]},{id:106,text:"En la Ley General de Educación:",sorted:!1,options:[{text:"No se atienden cuestiones vinculadas a la calidad educativa para todos.",correct:!1},{text:"Se enfatiza la descentralidad del sistema educativo.",correct:!1},{text:"Se establecen relaciones entre el sistema educativo y el mundo laboral.",correct:!0},{text:"Ninguna de las opciones es correcta.",correct:!1}]},{id:107,text:"Banning establece los siguientes componentes facilitadores de la cooperación entre familiares y docentes para fomentar la educación inclusiva",sorted:!1,options:[{text:"Competencia profesional, comunicación, respeto, compromiso, equidad y confianza.",correct:!0},{text:"Respeto, compromiso y confianza.",correct:!1},{text:"Competencia profesional y comunicación.",correct:!1},{text:"Competencia profesional, integración, respeto, compromiso, equidad y confianza.",correct:!1}]},{id:108,text:"Según la ley Moyano, la primera enseñanza elemental:",sorted:!1,options:[{text:"No era obligatoria.",correct:!1},{text:"Era obligatoria pero no gratuita.",correct:!1},{text:"Era obligatoria y gratuita, para aquellos que no pudieran pagarla.",correct:!0},{text:"Ninguna de las opciones es correcta.",correct:!1}]},{id:109,text:"El concepto de inclusión:",sorted:!1,options:[{text:"Implica que todos los alumnos de una comunidad aprendan juntos, independientemente de sus condiciones sociales o culturales.",correct:!1},{text:"Es más amplio que el de integración.",correct:!1},{text:"Implica que todos los alumnos de una comunidad aprendan juntos, independientemente de sus condiciones personales.",correct:!1},{text:"Todas las opciones son correctas.",correct:!0}]},{id:110,text:"Qué significa LOMCE:",sorted:!1,options:[{text:"Ley Orgánica para la Mejora de la Calidad Educativa.",correct:!0},{text:"Ley Orgánica para la Mejora de Centros Educativos.",correct:!1},{text:"Ley Orgánica para la Mejora de Colegios Españoles",correct:!1},{text:"Ley Orgánica para la Mejora de Comunidades Educativas.",correct:!1}]},{id:111,text:"En la LOGSE la presencia de la familia:",sorted:!1,options:[{text:"Es menor que en las leyes educativas anteriores.",correct:!0},{text:"No aparece en ninguna parte del documento.",correct:!1},{text:"Es igual que en las leyes educativas anteriores.",correct:!1},{text:"Es mayor que en las leyes educativas anteriores.",correct:!1}]},{id:112,text:"Marchesi y Martín (1998) clasifican las características de la sociedad de la información en los siguientes grupos:",sorted:!1,options:[{text:"Económicas, tecnológicas, políticas y educativas.",correct:!1},{text:"Económicas, tecnológicas, individuales y sociales.",correct:!1},{text:"Económicas, tecnológicas, políticas y sociales.",correct:!0},{text:"Ninguna de las opciones es correcta.",correct:!1}]},{id:113,text:"La LOGSE establece la escolaridad obligatoria:",sorted:!1,options:[{text:"Desde los 6 años, hasta los 16 (homologándolo a la Unión Europea).",correct:!0},{text:"Desde los 3 años, hasta los 16 (homologándolo a la Unión Europea).",correct:!1},{text:"Desde los 6 años hasta los 16 (permaneciendo por debajo de la escolarización obligatoria en la Unión Europea).",correct:!1},{text:"Desde los 3 años hasta los 16 (permaneciendo por debajo de la escolarización obligatoria de la Unión Europea).",correct:!1}]},{id:114,text:"La fase del proceso de transformación hacia una comunidad de aprendizaje, denominada sensibilización, consiste en:",sorted:!1,options:[{text:"Que el equipo directivo sensibilice a los agentes educativos sobre las necesidades de las que parte el proyecto de comunidad de aprendizaje.",correct:!1},{text:"Que el equipo directivo informe a los actores implicados sobre las líneas de acción que se llevarán a cabo.",correct:!1},{text:"Que todos los actores sociales implicados, analizan el contexto y la realidad de su escuela y discuten conocimientos y acciones necesarias.",correct:!0},{text:"Ninguna de las opciones es correcta.",correct:!1}]},{id:115,text:"La centralidad del aprendizaje, referida a las comunidades de aprendizaje quiere decir que:",sorted:!1,options:[{text:"El proceso de enseñanza-aprendizaje incluye a toda la comunidad, no solo a los alumnos.",correct:!0},{text:"El proceso de enseñanza-aprendizaje debe basarse en las altas expectativas.",correct:!1},{text:"El proceso de enseñanza-aprendizaje es responsabilidad exclusiva de los docentes.",correct:!1},{text:"El proceso de enseñanza-aprendizaje es responsabilidad de todos los miembros de la comunidad.",correct:!1}]},{id:116,text:'¿Cuál era el nombre de las primeras instituciones de enseñanza organizadas que surgieron en Mesopotamia, conocidas como las "casas de tablillas"?',sorted:!1,options:[{text:"Scriptorium",correct:!1},{text:"Agogé",correct:!1},{text:"Per Anj",correct:!1},{text:"Edubba",correct:!0}]},{id:117,text:"¿Qué sistema educativo estatal y obligatorio fue desarrollado en Esparta con el objetivo principal de formar soldados disciplinados y resistentes?",sorted:!1,options:[{text:"Paideia",correct:!1},{text:"Ludus litterarius",correct:!1},{text:"Scholé",correct:!1},{text:"Agogé",correct:!0}]},{id:118,text:"¿Qué concepto griego, compartido tanto por Atenas como por Esparta a pesar de sus diferencias, representaba la búsqueda de la excelencia integral del individuo en lo físico, intelectual y moral?",sorted:!1,options:[{text:"Utilitas",correct:!1},{text:"Eudaimonía",correct:!1},{text:"Mayéutica",correct:!1},{text:"Areté",correct:!0}]},{id:119,text:"¿Cuál de los siguientes términos era un rasgo distintivo de la educación en la antigua Roma, representando su enfoque en la utilidad práctica del conocimiento?",sorted:!1,options:[{text:"Dialéctica",correct:!1},{text:"Humanitas",correct:!1},{text:"Paideia",correct:!1},{text:"Utilitas",correct:!0}]},{id:120,text:"En la educación romana, el ludi magister era el responsable de la enseñanza en la etapa conocida como:",sorted:!1,options:[{text:"Escuela del rhetor",correct:!1},{text:"Escuela del grammaticus",correct:!1},{text:"Ludus litterarius",correct:!0},{text:"Academia",correct:!1}]},{id:121,text:"¿Qué figura de la Antigüedad Clásica defendía la búsqueda de la verdad mediante el método de la mayéutica (basado en preguntas para descubrir el conocimiento interior), criticando el saber utilitario de los sofistas?",sorted:!1,options:[{text:"Platón",correct:!1},{text:"Aristóteles",correct:!1},{text:"Quintiliano",correct:!1},{text:"Sócrates",correct:!0}]},{id:122,text:"Según Aristóteles, ¿cuáles son los tres pilares fundamentales en los que se apoya el proceso educativo orientado a la eudaimonía (felicidad)?",sorted:!1,options:[{text:"Transmisión, Cohesión y Autonomía",correct:!1},{text:"Gramática, Música y Gimnasia",correct:!1},{text:"Trivium, Quadrivium y Filosofía",correct:!1},{text:"Naturaleza, Hábito y Razón",correct:!0}]},{id:123,text:"Durante la Alta Edad Media, la Iglesia Católica fue la principal depositaria del saber. ¿Cuál de las siguientes instituciones no fue un centro educativo clave en este periodo?",sorted:!1,options:[{text:"Monasterios (con la schola interior y exterior)",correct:!1},{text:"Escuelas Catedralicias",correct:!1},{text:"Madrasas",correct:!1},{text:"Escuela del rhetor (romana)",correct:!0}]},{id:124,text:"¿Qué método pedagógico predominó en las universidades de la Baja Edad Media (como Bolonia y París), que combinaba la lectura comentada de textos (lectio) con el debate de cuestiones (disputatio)?",sorted:!1,options:[{text:"Humanismo",correct:!1},{text:"Mayéutica",correct:!1},{text:"Trivium",correct:!1},{text:"Escolástica",correct:!0}]},{id:125,text:"La educación en el Humanismo y el Renacimiento se caracterizó por:",sorted:!1,options:[{text:"El método escolástico.",correct:!1},{text:"La formación de soldados disciplinados.",correct:!1},{text:"El enfoque exclusivamente teocrático.",correct:!1},{text:"El desarrollo integral del individuo, revalorizando letras clásicas y ciencias.",correct:!0}]},{id:126,text:'¿Qué nación fue la primera en establecer la educación obligatoria mediante "Las Regulaciones Generales para las Escuelas de los Pueblos" en 1763?',sorted:!1,options:[{text:"Francia (durante la ilustración)",correct:!1},{text:"Inglaterra",correct:!1},{text:"Prusia",correct:!0},{text:"España",correct:!1}]},{id:127,text:"¿Qué invento del siglo XV fue identificado en la unidad como un factor que transformó profundamente la difusión y el acceso al conocimiento, multiplicando los libros de texto y facilitando la extensión de la alfabetización?",sorted:!1,options:[{text:"El telégrafo",correct:!1},{text:"El telescopio",correct:!1},{text:"La máquina de vapor",correct:!1},{text:"La imprenta de Gutenberg",correct:!0}]},{id:128,text:"Desde el punto de vista etimológico, la raíz latina educare se relaciona con la idea de:",sorted:!1,options:[{text:"Sacar, guiar o conducir hacia fuera.",correct:!1},{text:"Formación para la autonomía y el espíritu crítico.",correct:!1},{text:"Criar, alimentar y proteger, implicando la transmisión de saberes y normas.",correct:!0},{text:"Desarrollo de potencialidades innatas.",correct:!1}]},{id:129,text:'¿Qué raíz latina asociada a la educación significa "sacar, guiar o conducir hacia fuera", relacionada con el desarrollo de potencialidades y la autonomía?',sorted:!1,options:[{text:"Studium",correct:!1},{text:"Educere",correct:!0},{text:"Educare",correct:!1},{text:"Utilitas",correct:!1}]},{id:130,text:'¿Qué pensador concibió la educación como un fenómeno "eminentemente social", donde las generaciones adultas transmiten a los jóvenes los valores y normas para garantizar la cohesión y la continuidad cultural?',sorted:!1,options:[{text:"Immanuel Kant",correct:!1},{text:"Paulo Freire",correct:!1},{text:"Platón",correct:!1},{text:"Émile Durkheim",correct:!0}]},{id:131,text:'¿Qué autor propuso una educación basada en el diálogo horizontal y la construcción conjunta de conocimiento, rechazando la "visión bancaria" de la enseñanza?',sorted:!1,options:[{text:"Émile Durkheim",correct:!1},{text:"Immanuel Kant",correct:!1},{text:"Paulo Freire",correct:!0},{text:"Jean Piaget",correct:!1}]},{id:132,text:"¿Cómo se titula el documento de la UNESCO de 1996 que constituyó un hito en la reflexión pedagógica internacional al establecer los Cuatro Pilares de la Educación?",sorted:!1,options:[{text:"Replantear la educación",correct:!1},{text:"Reimaginar juntos nuestros futuros",correct:!1},{text:"La República",correct:!1},{text:"La educación encierra un tesoro",correct:!0}]},{id:133,text:"¿Cuál de las siguientes opciones NO es uno de los Cuatro Pilares de la Educación establecidos en el Informe Delors?",sorted:!1,options:[{text:"Aprender a conocer",correct:!1},{text:"Aprender a vivir juntos",correct:!1},{text:"Aprender a ser",correct:!1},{text:"Aprender a memorizar",correct:!0}]},{id:134,text:"¿Cuál de las dos dimensiones de la educación contemporánea se centra en el desarrollo de la autonomía, la creatividad, el sentido crítico y la autorrealización del estudiante?",sorted:!1,options:[{text:"Dimensión cultural",correct:!1},{text:"Dimensión política",correct:!1},{text:"Dimensión individual",correct:!0},{text:"Dimensión social",correct:!1}]},{id:135,text:"¿Qué función de la educación se relaciona con la inserción laboral, la adaptación a cambios tecnológicos, la productividad y la movilidad social?",sorted:!1,options:[{text:"Función socializadora",correct:!1},{text:"Función política",correct:!1},{text:"Función económica",correct:!0},{text:"Función cultural",correct:!1}]},{id:136,text:"¿Cómo se define un agente socializador según la unidad didáctica?",sorted:!1,options:[{text:"Una entidad que solo transmite conocimientos académicos formales.",correct:!1},{text:"Cualquier entidad que participa activamente en la transmisión sistemática o espontánea de normas, valores, roles y prácticas culturales a los miembros de una sociedad.",correct:!0},{text:"El individuo que internaliza el mundo objetivo de su sociedad.",correct:!1},{text:"Una institución que actúa únicamente en etapas posteriores del ciclo vital.",correct:!1}]},{id:137,text:"¿Cuál de los siguientes es considerado el agente socializador primario por excelencia?",sorted:!1,options:[{text:"La escuela.",correct:!1},{text:"Los medios de comunicación.",correct:!1},{text:"Las organizaciones laborales.",correct:!1},{text:"La familia.",correct:!0}]},{id:138,text:"¿Cuál de las siguientes es una de las tres funciones clave que cumple la familia en la socialización primaria, relacionada con el desarrollo del autoconcepto?",sorted:!1,options:[{text:"Transmisión de sistemas educativos.",correct:!1},{text:"Formación de la identidad subjetiva.",correct:!0},{text:"Entrenamiento laboral.",correct:!1},{text:"Formalización de roles.",correct:!1}]},{id:139,text:"Según Berger y Luckmann, ¿qué característica principal define a la socialización primaria?",sorted:!1,options:[{text:"Es siempre formal y planificada.",correct:!1},{text:"Se limita a la adquisición de roles laborales.",correct:!1},{text:"Ocurre en fases posteriores del ciclo vital.",correct:!1},{text:"Se caracteriza por su irreversibilidad emocional y cognitiva.",correct:!0}]},{id:140,text:"¿Cuál es un ejemplo paradigmático de un proceso informal de socialización en el ámbito familiar?",sorted:!1,options:[{text:"La legislación familiar.",correct:!1},{text:"Los sistemas educativos.",correct:!1},{text:"Los rituales familiares (como las comidas compartidas).",correct:!0},{text:"Los programas de onboarding laboral.",correct:!1}]},{id:141,text:"Según la Teoría Ecológica de Bronfenbrenner, ¿en qué sistema se sitúa la familia como el entorno de interacción directa más influyente en las primeras etapas de la vida?",sorted:!1,options:[{text:"Mesosistema",correct:!1},{text:"Exosistema",correct:!1},{text:"Macrosistema",correct:!1},{text:"Microsistema",correct:!0}]},{id:142,text:"¿Qué término se utiliza para describir la función de la familia al mediar entre el recién nacido y el orden social, filtrando y transmitiendo normas?",sorted:!1,options:[{text:"Exosistema",correct:!1},{text:"Andamiaje laboral",correct:!1},{text:"Tamiz",correct:!0},{text:"Cronosistema",correct:!1}]},{id:143,text:"¿Cuál fue la principal crítica de David Schneider a los estudios tradicionales de la familia y el parentesco?",sorted:!1,options:[{text:"Que la familia debe ser siempre nuclear.",correct:!1},{text:"Que estaban marcados por una visión androcéntrica y etnocéntrica, asumiendo que los lazos solo dependen de la biología.",correct:!0},{text:"Que el parentesco se basa únicamente en reglas de intercambio económico.",correct:!1},{text:"Que la socialización informal es irrelevante.",correct:!1}]},{id:144,text:"¿Qué sostiene la autora feminista Silvia Federici sobre el ideal de la familia tradicional?",sorted:!1,options:[{text:"Que es una realidad exclusivamente biológica.",correct:!1},{text:"Que es un sistema de apoyo afectivo irremplazable.",correct:!1},{text:"Que es una institución social y política que puede reproducir desigualdades de género.",correct:!0},{text:"Que su rol económico ha desaparecido por completo.",correct:!1}]},{id:145,text:"¿Qué modelo familiar predominaba en España durante la Etapa Demográfica Primitiva (hasta la Edad Contemporánea)?",sorted:!1,options:[{text:"Familia unipersonal.",correct:!1},{text:"Familia extensa o troncal.",correct:!0},{text:"Familia monoparental.",correct:!1},{text:"Familia homoparental.",correct:!1}]},{id:146,text:"¿Qué modelo familiar se consolidó en España durante la Etapa de Transición Demográfica, impulsada por la industrialización y la urbanización?",sorted:!1,options:[{text:"Familia trasnacional.",correct:!1},{text:"Familia de acogida.",correct:!1},{text:"Familia matrifocal.",correct:!1},{text:"Familia nuclear.",correct:!0}]},{id:147,text:"¿Cuál de los siguientes factores contribuyó directamente a la diversificación y pluralidad de los modelos familiares en España a partir de 1975?",sorted:!1,options:[{text:"El aumento de la tasa de natalidad.",correct:!1},{text:"La dependencia exclusiva del sector agrario.",correct:!1},{text:"La incorporación masiva de la mujer al mercado laboral.",correct:!0},{text:"El descenso de la esperanza de vida.",correct:!1}]},{id:148,text:"¿Qué implica el modelo de corresponsabilidad educativa?",sorted:!1,options:[{text:"Que la escuela asume toda la responsabilidad pedagógica formal.",correct:!1},{text:"Que la familia solo se encarga de las tareas informales.",correct:!1},{text:"Que la escuela evalúa la calidad de la familia.",correct:!1},{text:"Colaboración activa y diálogo permanente entre familia y escuela, reconociéndose mutuamente como agentes fundamentales de aprendizaje.",correct:!0}]},{id:149,text:"En relación con el bienestar infantil y el éxito académico, ¿qué factor se considera más determinante, según las investigaciones recientes?",sorted:!1,options:[{text:"La estructura nuclear de la familia.",correct:!1},{text:"La calidad de las relaciones, la estabilidad y el apoyo emocional (funcionamiento).",correct:!0},{text:"El alto número de miembros en el hogar.",correct:!1},{text:"La filiación biológica de los hijos.",correct:!1}]},{id:150,text:"¿Cómo se define una familia matrifocal?",sorted:!1,options:[{text:"Familia donde el hombre tiene múltiples esposas (poliginia).",correct:!1},{text:"Familia en la que solo conviven primos y tíos.",correct:!1},{text:"Familia centrada en mujeres (madres, abuelas) como figuras de autoridad y sustento económico.",correct:!0},{text:"Familias cuyos miembros residen en diferentes países (transnacional).",correct:!1}]},{id:151,text:'¿Qué término utiliza la nueva Ley de Familias de España (2023, con novedades para 2025) para reemplazar el concepto de "familia numerosa"?',sorted:!1,options:[{text:"Familias con baja renta per cápita.",correct:!1},{text:"Familias con mayores necesidades de apoyo a la crianza.",correct:!0},{text:"Familias con tres hijos o más.",correct:!1},{text:"Unidades domésticas de custodia compartida.",correct:!1}]},{id:152,text:"¿Cuál de los siguientes es un ejemplo de un proceso formal de socialización?",sorted:!1,options:[{text:"Dinámicas de juego infantil.",correct:!1},{text:"Consumo mediático.",correct:!1},{text:"Legislación familiar (como los permisos parentales).",correct:!0},{text:"Interacción espontánea entre los miembros.",correct:!1}]},{id:153,text:"¿Con qué se correlaciona la disfuncionalidad familiar, según estudios citados en la unidad?",sorted:!1,options:[{text:"Mejora de la cohesión grupal.",correct:!1},{text:"Alto rendimiento académico.",correct:!1},{text:"Mayor riesgo de fracaso escolar, problemas de conducta y dificultades emocionales.",correct:!0},{text:"Desarrollo de la autonomía personal.",correct:!1}]},{id:154,text:"¿En qué año se legalizó el divorcio en España, un factor clave en la diversificación de los modelos familiares?",sorted:!1,options:[{text:"1950",correct:!1},{text:"1981",correct:!0},{text:"2005",correct:!1},{text:"1975",correct:!1}]},{id:155,text:"¿Qué documento legal internacional, ratificado por España, reconoce explícitamente el derecho de los menores a ser escuchados y a que sus opiniones sean tenidas en cuenta?",sorted:!1,options:[{text:"Ley de Familias de España (2023).",correct:!1},{text:"Teoría Ecológica de Bronfenbrenner.",correct:!1},{text:"Convención sobre los Derechos del Niño (1989).",correct:!0},{text:"Real Decreto 157/2022 (Educación Emocional).",correct:!1}]},{id:156,text:"La corresponsabilidad como derecho de participación corresponde a",sorted:!1,options:[{text:"El centro educativo.",correct:!1},{text:"El docente y el centro educativo.",correct:!1},{text:"La familia.",correct:!0},{text:"La familia y el centro educativo.",correct:!1}]},{id:157,text:"¿Qué modelo de enseñanza es competencial y responsabiliza al estudiante de su proceso de EAF?",sorted:!1,options:[{text:"Innovador.",correct:!1},{text:"Posmoderno.",correct:!0},{text:"Moderno.",correct:!1},{text:"Tradicional.",correct:!1}]},{id:158,text:"El marco axiológico de la educación se refiere a",sorted:!1,options:[{text:"Las normas.",correct:!1},{text:"Los objetivos.",correct:!1},{text:"Los valores.",correct:!0},{text:"Los principios.",correct:!1}]},{id:159,text:"¿Dónde residen los límites del ideario de centro en el derecho a la educación?",sorted:!1,options:[{text:"En la Constitución.",correct:!0},{text:"En la libertad de cátedra.",correct:!1},{text:"En la LOMLOE.",correct:!1},{text:"En el proyecto educativo.",correct:!1}]},{id:160,text:"Las Comunidades de Aprendizaje (CREA) surgen en centros educativos que",sorted:!1,options:[{text:"Carecen de AMPA.",correct:!1},{text:"Sufren altas tasas de abandono escolar.",correct:!0},{text:"Se ubican en contextos rurales.",correct:!1},{text:"No disponen de fondos de apoyo.",correct:!1}]},{id:161,text:"La Sociedad Digital del Conocimiento está",sorted:!1,options:[{text:"Hibridada.",correct:!1},{text:"Hiperconectada.",correct:!0},{text:"Homogeneizada.",correct:!1},{text:"Centralizada.",correct:!1}]},{id:162,text:"La participación de las familias en la educación depende de",sorted:!1,options:[{text:"De la calidad.",correct:!1},{text:"Del AMPA.",correct:!1},{text:"De la implicación y la intensidad.",correct:!1},{text:"Lo dictado en la normativa.",correct:!0}]},{id:163,text:"La competencia digital es una competencia",sorted:!1,options:[{text:"Básica.",correct:!1},{text:"Transversal.",correct:!0},{text:"Profesional.",correct:!1},{text:"Específica.",correct:!1}]},{id:164,text:"Una característica esencial de las familias del S. XXI es",sorted:!1,options:[{text:"La diversidad.",correct:!0},{text:"El dinamismo.",correct:!1},{text:"La ortodoxia.",correct:!1},{text:"La homogeneidad.",correct:!1}]},{id:165,text:"La base de la relación indisoluble educación, familia y entorno social se encuentras establecidas por",sorted:!1,options:[{text:"La Constitución Española.",correct:!1},{text:"El Contrato Social de la Educación.",correct:!0},{text:"El informe Delors, la educación entierra un tesoro.",correct:!1},{text:"Los Tratados de la Unión Europea.",correct:!1}]},{id:166,text:"El proceso de EAF se refiere a",sorted:!1,options:[{text:"Enseñanza Abierta a la Formación.",correct:!1},{text:"Educación, Aprendizaje y Fomento.",correct:!1},{text:"Enseñanza, Aprendizaje y Formación.",correct:!0},{text:"Educación Alternativa Funcional.",correct:!1}]},{id:167,text:"Las RRSS se han convertido en el principal (...) del S. XXI.",sorted:!1,options:[{text:"Recurso.",correct:!1},{text:"Aplicación digital.",correct:!1},{text:"Medio de comunicación.",correct:!0},{text:"Soporte pedagógico.",correct:!1}]},{id:168,text:"Los PLE son recomendables para",sorted:!1,options:[{text:"Los procesos de EAF mediados.",correct:!0},{text:"El manejo de la RRSS.",correct:!1},{text:"La transformación digital del centro educativo.",correct:!1},{text:"La participación de las familias.",correct:!1}]},{id:169,text:"Las dinámicas positivas de participación de las familias dependen, entre otros factores:",sorted:!1,options:[{text:"De la motivación de los hijos.",correct:!1},{text:"Del dinamismo y las actitudes del docente.",correct:!1},{text:"De la ley en vigor.",correct:!0},{text:"De la receptividad de los agentes sociales.",correct:!1}]},{id:170,text:"El derecho a la educación en España se estableció en el año:",sorted:!1,options:[{text:"1949, coincidiendo con la Declaración de los Derechos Humanos.",correct:!1},{text:"1985, con la Ley Orgánica del Derecho a la Educación.",correct:!1},{text:"1901, coincidiendo con la creación del Ministerio de Instrucción Pública.",correct:!0},{text:"1978, Con la Constitución Española.",correct:!1}]},{id:171,text:"La función pedagógica de la educación reside en",sorted:!1,options:[{text:"El desarrollo integral de la persona.",correct:!0},{text:"Alfabetización informacional y mediática.",correct:!1},{text:"Socializar",correct:!1},{text:"Enculturizar",correct:!1}]},{id:172,text:"La identidad profesional se conforma:",sorted:!1,options:[{text:"En la formación inicial.",correct:!1},{text:"En el centro de trabajo.",correct:!0},{text:"En la profesionalización.",correct:!1},{text:"En la formación permanente.",correct:!1}]},{id:173,text:"La calidad de un sistema educativo no puede ser menor que",sorted:!1,options:[{text:"La de sus docentes.",correct:!0},{text:"La del AMPA.",correct:!1},{text:"La de sus estudiantes.",correct:!1},{text:"La de PAS.",correct:!1}]},{id:174,text:"¿En qué tipo de sociedad se enmarca la educación en la actualidad?",sorted:!1,options:[{text:"Industrial",correct:!1},{text:"de la información y del conocimiento",correct:!0},{text:"de la globalización",correct:!1},{text:"feudal",correct:!1}]},{id:175,text:"¿Cuál es el agente más influyente y decisivo en la educación?",sorted:!1,options:[{text:"la familia",correct:!0},{text:"el centro educativo",correct:!1},{text:"la administración educativa",correct:!1},{text:"la legislación educativa",correct:!1}]},{id:176,text:"¿Cuál es el objetivo prioritario de todas las condiciones que favorecen la función educativa?",sorted:!1,options:[{text:"un buen rendimiento académico",correct:!1},{text:"una óptima educación en valores",correct:!1},{text:"el desarrollo intelectual",correct:!1},{text:"el crecimiento personal",correct:!0}]},{id:177,text:"¿Cuál de las siguientes es una de las funciones que tiene la familia del siglo XXI respecto a la educación?",sorted:!1,options:[{text:"desarrollar la empatía y la solidaridad",correct:!0},{text:"contribuir a la incorporación de los hijos al mercado laboral",correct:!1},{text:"favorecer el aprendizaje colaborativo",correct:!1},{text:"permanecer al margen de la actividad del centro educativo",correct:!1}]},{id:178,text:"¿Con qué modelo se corresponde la familia moderna?",sorted:!1,options:[{text:"patriarcal",correct:!1},{text:"tradicional",correct:!1},{text:"autoritario",correct:!1},{text:"nuclear",correct:!0}]},{id:179,text:"¿Qué es una comunidad de aprendizaje?",sorted:!1,options:[{text:"un proyecto de aprendizaje y servicio diseñado por las familias para su aplicación en el centro educativo de sus hijos",correct:!1},{text:"un proyecto de educación en valores diseñado por las familias para su aplicación en el centro educativo de sus hijos",correct:!1},{text:"un proyecto para promover acuerdos y compromisos del municipio en aspectos relativos a la educación y la ciudadanía, en los diferentes sectores, estamentos, entidades y asociaciones",correct:!1},{text:"un proyecto de transformación de los centros escolares surgidos para dar respuesta a los nuevos retos educativos que plantea la sociedad actual, a través d la participación de todos",correct:!0}]},{id:180,text:"En Esparta, la educación estaba controlada por el Estado y se centraba en la disciplina, la resistencia y la obediencia.",sorted:!1,options:[{text:"Verdadero",correct:!0},{text:"Falso",correct:!1}]},{id:181,text:"La paideia representaba el ideal educativo egipcio, centrado en la formación integral del ciudadano.",sorted:!1,options:[{text:"Verdadero",correct:!1},{text:"Falso",correct:!0}]},{id:182,text:"Los templos y las escuelas de escribas, llamadas edubbas, eran los principales centros de enseñanza en Egipto.",sorted:!1,options:[{text:"Verdadero",correct:!1},{text:"Falso",correct:!0}]},{id:183,text:"Las niñas espartanas también recibían formación física para fortalecer su cuerpo y dar hijos fuertes a la polis.",sorted:!1,options:[{text:"Verdadero",correct:!0},{text:"Falso",correct:!1}]},{id:184,text:"La enseñanza en Mesopotamia se basaba principalmente en la copia de textos.",sorted:!1,options:[{text:"Verdadero",correct:!0},{text:"Falso",correct:!1}]},{id:185,text:"Sócrates criticaba duramente a los sofistas por su relativismo moral.",sorted:!1,options:[{text:"Verdadero",correct:!0},{text:"Falso",correct:!1}]},{id:186,text:"En Esparta no se valoraba la creatividad individual por encima de la lealtad al Estado.",sorted:!1,options:[{text:"Verdadero",correct:!0},{text:"Falso",correct:!1}]},{id:187,text:"Los sofistas enseñaban principalmente retórica y oratoria para triunfar en la vida pública.",sorted:!1,options:[{text:"Verdadero",correct:!0},{text:"Falso",correct:!1}]},{id:188,text:"En Mesopotamia, las instituciones educativas eran conocidas como escuelas de escribas o edubbas.",sorted:!1,options:[{text:"Verdadero",correct:!0},{text:"Falso",correct:!1}]},{id:189,text:"Los sofistas enfatizaban la capacidad de persuasión del individuo.",sorted:!1,options:[{text:"Verdadero",correct:!0},{text:"Falso",correct:!1}]},{id:190,text:"En Esparta, la música y la filosofía no eran los pilares fundamentales de la educación.",sorted:!1,options:[{text:"Verdadero",correct:!0},{text:"Falso",correct:!1}]},{id:191,text:"En Atenas, el objetivo de la educación era formar ciudadanos críticos y participativos.",sorted:!1,options:[{text:"Verdadero",correct:!0},{text:"Falso",correct:!1}]},{id:192,text:"La escritura cuneiforme era una parte esencial del aprendizaje en Mesopotamia.",sorted:!1,options:[{text:"Verdadero",correct:!0},{text:"Falso",correct:!1}]},{id:193,text:"El sistema educativo espartano se llamaba agogé.",sorted:!0,options:[{text:"Verdadero",correct:!0},{text:"Falso",correct:!1}]},{id:194,text:"La educación griega daba gran importancia tanto al cuerpo como al espíritu.",sorted:!1,options:[{text:"Verdadero",correct:!0},{text:"Falso",correct:!1}]},{id:195,text:"La Academia de Platón, fundada en 387 a.C., fue la primera comunidad intelectual organizada de la historia.",sorted:!1,options:[{text:"Verdadero",correct:!0},{text:"Falso",correct:!1}]},{id:196,text:"Los fenicios crearon un alfabeto consonántico y su educación se centraba en matemáticas y astronomía para la navegación y el comercio.",sorted:!1,options:[{text:"Verdadero",correct:!0},{text:"Falso",correct:!1}]},{id:197,text:"En Mesopotamia, la enseñanza estaba bifurcada en dos líneas: una funcional y otra sacerdotal.",sorted:!1,options:[{text:"Verdadero",correct:!1},{text:"Falso",correct:!0}]},{id:198,text:"Los fenicios desarrollaron la escritura cuneiforme utilizada en Mesopotamia.",sorted:!1,options:[{text:"Verdadero",correct:!1},{text:"Falso",correct:!0}]},{id:199,text:"En la etapa demográfica primitiva la estructura familiar más común es la nuclear, mientras que en la etapa de transición demográfica predomina la familia extensa.",sorted:!1,options:[{text:"Verdadero",correct:!1},{text:"Falso",correct:!0}]},{id:200,text:"Una de las principales críticas que se puede realizar a la institución familiar es que, tradicionalmente, ha mantenido una visión androcentrista, centrada en la figura masculina, y etnocentrista, basada en normas y valores propios de la cultura occidental.",sorted:!1,options:[{text:"Verdadero",correct:!0},{text:"Falso",correct:!1}]},{id:201,text:"Agentes secundarios de socialización son aquellos que interactúan con el individuo en las etapas iniciales de su desarrollo (infancia y niñez), ejerciendo una influencia profunda y duradera.",sorted:!1,options:[{text:"Verdadero",correct:!1},{text:"Falso",correct:!0}]},{id:202,text:'En la teoría ecológica de Bronfenbrenner, el "macrosistema" se refiere a los cambios y transiciones vitales a lo largo del tiempo, así como a los acontecimientos históricos que afectan al desarrollo.',sorted:!1,options:[{text:"Verdadero",correct:!1},{text:"Falso",correct:!0}]},{id:203,text:"Aprender a conocer, aprender a hacer, aprender a ser y aprender a convivir son:",sorted:!1,options:[{text:"las cuatro funciones de las instituciones educativas",correct:!1},{text:"los cuatro pilares de la education según el informe Delors (UNESCO)",correct:!0},{text:"los cuatro principios de la educación durante el imperio romano",correct:!1},{text:"las cuatro dimensiones que caracterizan el isomorfismo institucional",correct:!1}]},{id:204,text:"El término educación bancaria es:",sorted:!1,options:[{text:"Propuesto por Émile Durkheim y representa una crítica a la educación tradicional",correct:!1},{text:"Propuesto por Paulo Freire y representa la importancia de la relación horizontal entre docente y alumno",correct:!1},{text:"Una teoría que surge con el movimiento de la Escuela Nueva",correct:!1},{text:"Propuesto por Paulo Freire y representa una crítica a la educación tradicional",correct:!0}]},{id:205,text:"La paideia es:",sorted:!1,options:[{text:"El modelo educativo que se desarrolló durante la Grecia antigua.",correct:!0},{text:"El modelo educativo que se desarrolló durante la Edad Media.",correct:!1},{text:"El modelo educativo que se desarrolló durante el movimiento de la Escuela Nueva.",correct:!1},{text:"El modelo educativo que se desarrolló durante la etapa demográfica primitiva en España.",correct:!1}]},{id:206,text:'Aristóteles propuso una teoría educativa orientada a la "eudaimonia", que significa:',sorted:!1,options:[{text:"La felicidad, entendida como la realización plena del potencial humano a través de la virtud",correct:!0},{text:"La aplicación de metodologías activas",correct:!1},{text:"El isomorfismo institucional",correct:!1},{text:"Un modelo educativo que se traduce en la agogé",correct:!1}]},{id:207,text:"La familia es:",sorted:!1,options:[{text:"Agente de socialización secundaria",correct:!1},{text:"Una estructura social diversa",correct:!0},{text:"Una dimensión del cronosistema de la teoría ecológica de Bronfenbrenner",correct:!1},{text:"Uniforme",correct:!1}]},{id:208,text:"El paso de un modelo familiar dominante y homogéneo a una realidad plural, flexible y en constante transformación está asociado a la:",sorted:!1,options:[{text:"Etapa de la transición demográfica",correct:!1},{text:"Etapa demográfica primitiva",correct:!1},{text:"Convención sobre los Derechos del Niño (1989)",correct:!1},{text:"Etapa demográfica evolucionada",correct:!0}]},{id:209,text:"La familia monoparental se caracteriza por:",sorted:!1,options:[{text:"La convivencia de dos progenitores y uno o varios hijos.",correct:!1},{text:"La convivencia de un solo progenitor (madre o padre) con uno o varios hijos.",correct:!0},{text:"La convivencia exclusiva de familiares de distintas generaciones sin progenitores.",correct:!1},{text:"Un modelo familiar propio de la etapa demográfica primitiva.",correct:!1}]},{id:210,text:"Una institución se define como",sorted:!1,options:[{text:"Un conjunto de personas unidas por vínculos afectivos y biológicos.",correct:!1},{text:"Un conjunto de normas, reglas, prácticas y estructuras organizadas que regulan el comportamiento de las personas y orientan la vida colectiva.",correct:!0},{text:"Una organización de carácter temporal sin funciones reguladoras.",correct:!1},{text:"Un sistema informal que carece de legitimidad social y durabilidad.",correct:!1}]},{id:211,text:"Las instituciones presentan una serie de características fundamentales, entre las que se encuentran la normatividad, la durabilidad, la arquitectura organizacional, la legitimidad social y la función reguladora. ¿Qué se entiende por arquitectura organizacional de una institución?",sorted:!1,options:[{text:"El conjunto de normas y reglas que regulan el comportamiento de los miembros de la sociedad.",correct:!1},{text:"La capacidad de la institución para perdurar en el tiempo más allá de las personas que la integran.",correct:!1},{text:"La estructura interna de la institución, definida por roles, funciones y jerarquías que organizan su funcionamiento.",correct:!0},{text:"La estructura interna de la institución, definida por roles, funciones y jerarquías que organizan su funcionamiento, así como los edificios y las infraestructuras, como las aulas o los espacios de recreo, por ejemplo.",correct:!1}]},{id:212,text:"En el análisis sociológico de la escuela como institución, el concepto de isomorfismo institucional permite explicar que:",sorted:!1,options:[{text:'Los centros educativos convergen hacia la "Educación bancaria".',correct:!1},{text:"Las escuelas reproducen prácticas, estructuras y discursos semejantes porque responden a presiones externas e internas que favorecen la legitimidad social, incluso cuando dichas prácticas no mejoran los resultados educativos.",correct:!0},{text:"La homogeneidad entre centros escolares se debe principalmente a la autonomía de los equipos docentes y a la innovación metodológica.",correct:!1},{text:"El sistema educativo evoluciona de forma lineal hacia modelos más eficaces gracias a procesos de selección basados en el rendimiento académico.",correct:!1}]},{id:213,text:"Según la Teoría Ecológica del Desarrollo Humano de Bronfenbrenner, el desarrollo de la persona está influido por distintos sistemas ambientales interrelacionados. ¿Qué sistema representa el nivel de influencia más inmediato y cuál corresponde al nivel contextual más amplio en la teoría?",sorted:!1,options:[{text:"El mesosistema y el cronosistema",correct:!1},{text:"El microsistema y el macrosistema",correct:!1},{text:"El exosistema y el mesosistema",correct:!1},{text:"El microsistema y el cronosistema",correct:!0}]}];export{e as EESF_QUESTIONS};